 content=`<p class="legend">${t('Reference ranges copied from your form. Red cells indicate an out-of-range reading or an alarm; blanks mean no reading.','Plages de référence reprises de votre formulaire. Une case rouge indique une mesure hors plage ou une alarme ; une case vide signifie aucune mesure.')}</p><details class="equipment-node energy-register-section" open><summary><span class="equipment-summary-name"><strong>${t('Utility parameters','Paramètres utilités')}</strong></span><span class="equipment-child-count">${flow.utilityParameters.length} ${t('parameters','paramètres')}</span></summary><div class="equipment-node-body"><div class="energy-matrix" tabindex="0" role="region" aria-label="${t('Monthly utility checks','Contrôles mensuels des utilités')}"><table><thead><tr><th>${t('Installation','Installation')}</th><th>${t('Zone','Zone')}</th><th>${t('Parameter','Paramètre')}</th><th>Min</th><th>Max</th>${Array.from({length:days},(_,i)=>`<th scope="col">${i+1}</th>`).join('')}</tr></thead><tbody>${flow.utilityParameters.map(spec=>`<tr><th scope="row">${t(...spec.installation)}</th><td>${t(...spec.zone)}</td><td>${t(...spec.title)}${spec.unit?' ('+spec.unit+')':''}</td><td>${spec.min ?? '—'}</td><td>${spec.max ?? '—'}</td>${Array.from({length:days},(_,i)=>{const r=readingFor(i+1),v=r?.values[spec.key],alert=v!=null && (spec.type==='alarm'?v===1:spec.min!=null && (v<spec.min || v>spec.max));return `<td class="${alert?'utility-alert':''}">${writable?energyCell('utility',spec,energyMonth+'-'+String(i+1).padStart(2,'0'),v):v==null?'—':spec.type==='state'?v==='Running'?t('Running','Marche'):t('Stopped','Arrêt'):esc(v)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></div></details>`;
