function priorityChart(chartRecords) {
    const priorities=['P1','P2','P3','P4'], colors=['#b9544a','#d89249','#2175a6','#18894f'];
    const counts=priorities.map(priority=>chartRecords.filter(r=>r.priority===priority).length);
    const unspecified=chartRecords.length-counts.reduce((sum,count)=>sum+count,0);
    if(unspecified) { priorities.push('—'); colors.push('#97aab6'); counts.push(unspecified); }
    let stop=0;
    const slices=counts.map((count,i)=>{const start=stop;stop+=chartRecords.length?count/chartRecords.length*100:0;return `${colors[i]} ${start}% ${i===counts.length-1?100:stop}%`;});
    const donut=chartRecords.length?`conic-gradient(${slices.join(',')})`:'#e4ecf1';
return `<section class="panel pulse-panel"><div class="panel-head"><div><h2>${t('Interventions by priority','Interventions par priorité')}</h2><p>${priorityScope==='open'?t('Open interventions','Interventions ouvertes'):t('Including closed and preventive interventions','Y compris les interventions clôturées et préventives')}</p></div><div class="priority-scope" role="group" aria-label="${t('Intervention scope','Périmètre des interventions')}"><button type="button" data-priority-scope="open" aria-pressed="${priorityScope==='open'}" class="${priorityScope==='open'?'active':''}">${t('Open','Ouvertes')}</button><button type="button" data-priority-scope="all" aria-pressed="${priorityScope==='all'}" class="${priorityScope==='all'?'active':''}">${t('All','Toutes')}</button></div></div><div class="priority-chart"><div class="priority-donut" style="background:${donut}" role="img" aria-label="${t('Interventions by priority','Interventions par priorité')}: ${priorities.map((p,i)=>`${p==='—'?t('Unspecified','Non définie'):p} ${counts[i]}`).join(', ')}"><div class="priority-donut-center"><strong>${chartRecords.length}</strong><span>${priorityScope==='open'?t('open','ouvertes'):t('total','au total')}</span></div></div><div class="priority-legend">${priorities.map((priority,i)=>`<div class="priority-legend-row"><span class="priority-dot" style="background:${colors[i]}"></span><strong>${priority==='—'?t('Unspecified','Non définie'):priority}</strong><span>${counts[i]}</span></div>`).join('')}</div></div></section>`;
}

function failureTrendView() {
 const rows=equipmentFailureTrend(db,trendEquipment,trendPeriod,trendAnnual);
 const unit=trendAnnual?t('days','jours'):t('hours','heures'),peak=Math.max(1,...rows.flatMap(r=>[r.stopped,r.anomaly]));
 const magnitude=10**Math.floor(Math.log10(peak/4)),step=[1,2,2.5,5,10].map(n=>n*magnitude).find(n=>n>=peak/4),max=step*4;
 const format=n=>n.toLocaleString(db.language==='fr'?'fr-DZ':'en-GB',{maximumFractionDigits:2});
 return `<section class="panel failure-trend"><div class="panel-head"><div><h2>${t('Equipment failure duration','Durée des anomalies et arrêts')}</h2><p>${t('Estimated from reported impact until work completion. Overlaps count once per equipment; stopped time takes precedence.','Estimation depuis le signalement jusqu’à la fin des travaux. Les chevauchements comptent une seule fois par équipement ; les arrêts sont prioritaires.')}</p></div></div><div class="kpi-filters"><label class="field"><span>${t('Equipment / zone','Équipement / zone')}</span><select data-trend-filter="equipment"><option value="">${t('All equipment','Tous les équipements')}</option>${orderedEquipment().map(e=>`<option value="${esc(e.id)}" ${e.id===trendEquipment?'selected':''}>${esc(path(e.id))}</option>`).join('')}</select></label><label class="field"><span>${t('View','Vue')}</span><select data-trend-filter="mode"><option value="month" ${trendAnnual?'':'selected'}>${t('Month · hours per day','Mois · heures par jour')}</option><option value="year" ${trendAnnual?'selected':''}>${t('Year · days per month','Année · jours par mois')}</option></select></label><label class="field"><span>${trendAnnual?t('Year','Année'):t('Month','Mois')}</span><input data-trend-filter="${trendAnnual?'year':'month'}" type="${trendAnnual?'number':'month'}" min="${trendAnnual?'2000':'2000-01'}" max="${trendAnnual?'2200':'2200-12'}" value="${esc(trendAnnual?trendPeriod.slice(0,4):trendPeriod)}"></label></div><div class="failure-legend"><span><i class="anomaly-key"></i>${t('Running with anomaly','Fonctionne avec anomalie')}</span><span><i class="stopped-key"></i>${t('Stopped','Arrêté')}</span></div>${rows.length?`<p>${t('Total','Total')} : ${format(rows.reduce((n,r)=>n+r.anomaly,0))} ${unit} · ${t('anomaly','anomalie')} / ${format(rows.reduce((n,r)=>n+r.stopped,0))} ${unit} · ${t('stopped','arrêt')}</p>${failureTrendChart(rows,max,step,unit,format)}<details><summary>${t('View exact values','Voir les valeurs exactes')}</summary><div class="table-wrap"><table><thead><tr><th>${trendAnnual?t('Month','Mois'):t('Day','Jour')}</th><th>${t('Anomaly','Anomalie')} (${unit})</th><th>${t('Stopped','Arrêt')} (${unit})</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.label}</td><td>${format(r.anomaly)}</td><td>${format(r.stopped)}</td></tr>`).join('')}</tbody></table></div></details>`:`<p>${t('Select an equipment in the filter above to see its graph.','Sélectionnez un équipement dans le filtre ci-dessus pour afficher son graphique.')}</p>`}<p class="source-note">${t('Yearly days = recorded hours ÷ 24. Zone and all-equipment totals add equipment durations; they can exceed calendar hours. missing completion times are excluded. These are reported-state estimates, not machine sensor measurements.','Jours annuels = heures enregistrées ÷ 24. Les totaux par zone et de tous les équipements additionnent les durées et peuvent dépasser les heures calendaires. les fins manquantes sont exclues. Il s’agit d’estimations selon les signalements, pas de mesures par capteur.')}</p></section>`;
}

function failureTrendChart(rows,max,step,unit,format) {
 const width=Math.max(800,rows.length*48+96),left=72,top=36,bottom=300,pitch=(width-left-24)/rows.length;
 const label=r=>trendAnnual?new Date(Date.UTC(2026,r.label-1,1)).toLocaleString(db.language,{month:'short',timeZone:'UTC'}):r.label;
 return `<div class="failure-chart-scroll"><svg class="failure-chart-svg" viewBox="0 0 ${width} 360" role="img" aria-labelledby="failure-chart-title failure-chart-desc"><title id="failure-chart-title">${t('Equipment failure duration','Durée des anomalies et arrêts')}</title><desc id="failure-chart-desc">${esc(unit)} · ${t('Orange: running with anomaly. Red: stopped. Exact values are available in the table below.','Orange : fonctionne avec anomalie. Rouge : arrêté. Les valeurs exactes sont disponibles dans le tableau ci-dessous.')}</desc><text x="${left}" y="20" class="chart-unit">${esc(unit)}</text>${[0,1,2,3,4].map(i=>{const y=bottom-i*(bottom-top)/4;return `<line x1="${left}" x2="${width-24}" y1="${y}" y2="${y}" class="chart-grid ${i===0?'chart-baseline':''}"/><text x="${left-12}" y="${y+5}" text-anchor="end" class="chart-tick">${format(step*i)}</text>`;}).join('')}${rows.map((r,i)=>{const x=left+i*pitch+pitch/2;return `<g class="chart-group" tabindex="0" role="img" aria-label="${esc(label(r))}: ${t('Anomaly','Anomalie')} ${format(r.anomaly)} ${unit}; ${t('Stopped','Arrêt')} ${format(r.stopped)} ${unit}"><title>${esc(label(r))} · ${t('Anomaly','Anomalie')}: ${format(r.anomaly)} ${unit} · ${t('Stopped','Arrêt')}: ${format(r.stopped)} ${unit}</title>${['anomaly','stopped'].map((key,j)=>{const height=r[key]/max*(bottom-top);return `<rect x="${x+(j?2:-18)}" y="${bottom-height}" width="16" height="${height}" rx="2" class="chart-${key}"/>`;}).join('')}<text x="${x}" y="324" text-anchor="middle" class="chart-tick">${esc(label(r))}</text></g>`;}).join('')}<text x="${left}" y="352" class="chart-unit">${trendAnnual?t('Month','Mois'):t('Day of month','Jour du mois')}</text></svg></div>${rows.every(r=>!r.anomaly&&!r.stopped)?`<p class="source-note">${t('No anomaly or stoppage recorded for this period.','Aucune anomalie ni aucun arrêt enregistré sur cette période.')}</p>`:''}`;
}

globalThis.addEventListener?.('beforeunload',e=>{if(energyDrafts.size){e.preventDefault();e.returnValue='';}});
